// Builds airhub_bundle.lua from the module .lua files in this folder.
// Usage:  node build_bundle.js
// Requires Node.js on the PC (not in Roblox).
const fs = require("fs");
const path = require("path");

const dir = path.resolve(process.argv[2] || __dirname);
const out = path.resolve(process.argv[3] || path.join(dir, "airhub_bundle.lua"));

const CORE = [
  "00_ui_lib.lua",
  "01_core.lua",
  "02_aimbot.lua",
  "03_antiaim.lua",
  "04_wallhack.lua",
  "05_movement.lua",
  "06_world.lua",
  "07_exploits.lua",
  "08_settings.lua",
];
const EXTRAS = ["arsenal_extra_tab.lua", "rivals_extra_tab.lua"];

function longQuote(src) {
  for (let level = 0; level < 32; level++) {
    const close = "]" + "=".repeat(level) + "]";
    if (!src.includes(close)) {
      const open = "[" + "=".repeat(level) + "[";
      return open + "\n" + src + "\n" + close;
    }
  }
  throw new Error("cannot find a safe long-bracket delimiter");
}

function entry(name, extra) {
  const full = path.join(dir, name);
  if (!fs.existsSync(full)) throw new Error("missing " + full);
  const src = fs.readFileSync(full, "utf8").replace(/\r\n/g, "\n");
  return "    { name = " + JSON.stringify(name) +
         ", extra = " + (extra ? "true" : "false") +
         ", src = " + longQuote(src) + " },";
}

const modules = [];
for (const name of CORE) modules.push(entry(name, false));
for (const name of EXTRAS) modules.push(entry(name, true));

const header = `--// ============================================================================
--// AirHub — ALL-IN-ONE bundle (no readfile / no HttpGet needed)
--// Generated by build_bundle.js from:
--//   00_ui_lib, 01_core, 02_aimbot, 03_antiaim, 04_wallhack,
--//   05_movement, 06_world, 07_exploits, 08_settings
--//   + arsenal_extra_tab, rivals_extra_tab
--//
--// Loads every module in the correct order via loadstring().
--// Repeat launches unload the previous AirHub automatically.
--// Press RightShift to open the menu.
--// ============================================================================

local MODULES = {
`;

const footer = `}

--// ----------------------------------------------------------------------------
--// Options
--// ----------------------------------------------------------------------------
local LOAD_EXTRAS   = true  -- Arsenal / Rivals tabs (set false if unwanted)
local AUTO_UNLOAD   = true  -- unload a previously running AirHub first
local STOP_ON_ERROR = true  -- stop the core chain on the first error
local VERBOSE       = true  -- print progress

--// ----------------------------------------------------------------------------
--// Helpers
--// ----------------------------------------------------------------------------
local function genv()
    if type(getgenv) == "function" then return getgenv() end
    return _G
end

local function log(msg)
    if VERBOSE then print("[AirHub bundle] " .. tostring(msg)) end
end

local function fail(msg)
    error("[AirHub bundle] " .. tostring(msg), 0)
end

local function unloadPrevious()
    local g = genv()
    local Hg = g.AirHub
    local win = g.airhubUI_Window

    -- Rivals is not cleaned by 01_core.OnUnload — restore weapon stats.
    if Hg and Hg.Rivals and Hg.Rivals.Functions and Hg.Rivals.Functions.StopAll then
        pcall(Hg.Rivals.Functions.StopAll)
    end

    if win and type(win.Unload) == "function" then
        log("unloading previous AirHub...")
        pcall(function() win:Unload() end)
    end

    -- If a previous run died before cleanup, restore Mouse.Hit/Target.
    local restore = g.__AirHubMHTRestore
    if type(restore) == "function" then
        local players = game:GetService("Players")
        if players.LocalPlayer then
            pcall(function() players.LocalPlayer.GetMouse = restore end)
        end
        g.__AirHubMHTRestore = nil
    end

    g.AirHub = nil
    g.airhubUI = nil
    g.airhubUI_Window = nil
end

--// ----------------------------------------------------------------------------
--// Main
--// ----------------------------------------------------------------------------
local function main()
    if type(loadstring) ~= "function" then
        fail("Roblox executor with loadstring() required")
    end

    log("starting (self-contained bundle)")

    if AUTO_UNLOAD then
        unloadPrevious()
    else
        local g = genv()
        if g.AirHub and g.AirHub._CoreLoaded then
            warn("[AirHub bundle] AirHub is already loaded. Set AUTO_UNLOAD = true for a clean reload.")
        end
    end

    local list, optional = {}, {}
    for _, m in ipairs(MODULES) do
        if not m.extra or LOAD_EXTRAS then
            list[#list + 1] = m
            if m.extra then optional[m.name] = true end
        end
    end

    local total = #list
    local failed = 0
    local started = os.clock()

    for i, m in ipairs(list) do
        local t0 = os.clock()

        local chunk, compileErr = loadstring(m.src, "=" .. m.name)
        if not chunk then
            failed = failed + 1
            warn(string.format("[AirHub bundle] compile %s: %s", m.name, tostring(compileErr)))
            if STOP_ON_ERROR and not optional[m.name] then
                fail("stopped at " .. m.name)
            end
        else
            local ok, runErr = pcall(chunk)
            local ms = math.floor((os.clock() - t0) * 1000 + 0.5)
            if ok then
                log(string.format("[%d/%d] %s OK (%d ms)", i, total, m.name, ms))
            else
                failed = failed + 1
                warn(string.format("[AirHub bundle] runtime %s: %s", m.name, tostring(runErr)))
                if STOP_ON_ERROR and not optional[m.name] then
                    fail("stopped at " .. m.name)
                end
            end
        end

        task.wait()
    end

    local secs = string.format("%.1f", os.clock() - started)
    if failed == 0 then
        log(string.format("done: %d/%d modules in %ss", total, total, secs))
        log("press RightShift to open the menu")
    else
        warn(string.format("[AirHub bundle] finished with errors: %d/%d loaded, %d failed",
            total - failed, total, failed))
    end

    return failed == 0
end

return main()
`;

const bundle = header + modules.join("\n") + "\n" + footer;
fs.writeFileSync(out, bundle, "utf8");
console.log("wrote " + out + " (" + fs.statSync(out).size + " bytes, " + modules.length + " modules)");
